  private getPaletteForScheme(
    colorTokens: Readonly<{
      dark: Readonly<Record<ShadeValue, string>>;
      light: Readonly<Record<ShadeValue, string>>;
    }>,
    colorScheme: any = 'system'
  ): Record<string, string> {
    const lightPalette = colorTokens.light;
    const darkPalette = colorTokens.dark;

    switch (colorScheme) {
      case 'dark': {
        return darkPalette;
      }
      case 'light': {
        return lightPalette;
      }
      case 'system': {
        // Create a new palette with light-dark() for each shade
        return Object.fromEntries(
          Object.entries(lightPalette).map(([shade, lightColor]: readonly [string, string]) => {
            const shadeNum = Number(shade);
            const darkColor = isShadeValue(shadeNum) ? darkPalette[shadeNum] : lightColor;
