{"version":3,"file":"local-storage.cjs","names":[],"sources":["../../src/utils/local-storage.ts"],"sourcesContent":["const createStorageManager = <T>(
  key: string,
  defaultValue: T
): {
  defaultValue: T;
  isAvailable: () => boolean;
  load: () => null | T;
  remove: () => void;
  safeLoad: () => null | T;
  safeSave: (value: T) => void;
  save: (value: T) => void;
} => {
  const safeLoad = (): null | T => {
    if (!isStorageAvailable()) {
      globalThis.console.warn(`Cannot load ${key}: localStorage not available`);
      return null;
    }

    try {
      const storedValue = globalThis.localStorage.getItem(key);
      return storedValue ? JSON.parse(storedValue) : null;
    } catch (error) {
      globalThis.console.error(`Error loading ${key} from localStorage:`, error);
      return null;
    }
  };

  const safeSave = (value: T): void => {
    if (!isStorageAvailable()) {
      globalThis.console.warn(`Cannot save ${key}: localStorage not available`);
      return;
    }

    try {
      globalThis.localStorage.setItem(key, JSON.stringify(value));
    } catch (error) {
      globalThis.console.error(`Error saving ${key} to localStorage:`, error);
    }
  };

  const safeRemove = (): void => {
    if (!isStorageAvailable()) {
      globalThis.console.warn(`Cannot remove ${key}: localStorage not available`);
      return;
    }

    try {
      globalThis.localStorage.removeItem(key);
    } catch (error) {
      globalThis.console.error(`Error removing ${key} from localStorage:`, error);
    }
  };

  return {
    defaultValue,
    isAvailable: isStorageAvailable,
    load: safeLoad,
    remove: safeRemove,
    safeLoad,
    safeSave,
    save: safeSave,
  };
};

const isStorageAvailable = (): boolean => {
  try {
    // Check if localStorage is available and not blocked
    return true;
  } catch (error) {
    globalThis.console.warn('localStorage is not available:', error);
    return false;
  }
};

export { createStorageManager, isStorageAvailable };
