{"version":3,"file":"context.cjs","names":[],"sources":["../../../../src/components/organisms/theme/context.tsx"],"sourcesContent":["import { createContext, useContext, useEffect, useState } from 'react';

type Theme = 'dark' | 'light';

const isTheme = (theme: unknown): theme is Theme =>
  theme === 'light' || theme === 'dark';

interface ThemeContextType {
  setTheme: (theme: Theme) => void;
  theme: Theme;
}

const ThemeContext = createContext<ThemeContextType>({
  setTheme: () => {
    // Default no-op implementation
  },
  theme: 'dark',
});

const ThemeProvider = ({
  children,
  defaultTheme = 'dark',
}: any) => {
  const [theme, setTheme] = useState<Theme>(() => {
    const savedTheme = globalThis.localStorage.getItem('theme');
    return isTheme(savedTheme) ? savedTheme : defaultTheme;
  });

  useEffect(() => {
    globalThis.localStorage.setItem('theme', theme);
    globalThis.document.documentElement.classList.remove('light', 'dark');
    globalThis.document.documentElement.classList.add(theme);
  }, [theme]);

  return (
    <ThemeContext.Provider value={{ setTheme, theme }}>
      {children}
    </ThemeContext.Provider>
  );
};

const useTheme = () => {
  const context = useContext(ThemeContext) as ThemeContextType | undefined;
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
};

export { ThemeContext, ThemeProvider, useTheme };
